 CURRENT=i;ACCENT=accent;PEOPLE=[];SCENES=[];LINE=0;FLAGS=[];CLUES=[];INITIAL={'credibility':60,'readiness':50,'trust':55,'risk':25,'cash':100,'composure':60,'safeguards':0};BOUNDS={k:[0,100] for k in INITIAL};FUSES=[];ENDINGS=[]
