  ev.append(dict(id=f'event-{chapter}-{j:02}',window=dict(dayMin=sc['day'],dayMax=200),weight=1+j%3,cooldown=1,once=True,lines=[line(p['id'],specific[0])],effects=[specific[1],dict(chip='A seeded check-in exposed another operating constraint.')]))
