 manifests=dict(id=CURRENT,title=TITLES[ALL.index(CURRENT)],tagline=tagline,company=company,status='draft',version='2.0.0',minPlatformVersion='1.0.0',palette=dict(bg='#101b22',ink='#f4f2e7',accent=ACCENT),fonts=['Inter','DM Serif Display'],difficulty=dict(guided='Preview effects and see decision hints.',standard='Read the situation without previews.',sharp='Hide soft meters and handle extra check-ins.'),entranceArt=f'/levels/{CURRENT}/art/backgrounds/{SCENES[0]["background"]}.svg',estimatedMinutes=25,startScene=SCENES[0]['id'],scenes=[s['id'] for s in SCENES],people=[p['id'] for p in PEOPLE],assetsBudgetKB=3072,voiceCast={},labels='Simulated company, authored scenarios, expert review pending',flagKey=CURRENT,minEvents=events,systemic=True,launchCandidate=CURRENT in ['deadlock','invisible-wall','feature-factory'],reviewGates={g:'pending' for g in ['design','content','accessibility-manual','performance','security','playtest','domain']},acts=acts)
